/* 분류마다 항목 이름이 조금씩 달라서 화면에서 쓰는 이름으로 한 번 맞춰준다 */
const HIKE_LEVEL = { easy:"쉬움 — 초보도 OK", mid:"보통 — 등산화 권장", hard:"힘듦 — 체력 필요" };
const BUG_TXT = { 1:"벌레 거의 없음", 2:"벌레 보통 — 여름엔 기피제", 3:"벌레 많음 — 긴옷·기피제 필수" };
const FEE_CATS = { fest:1, valley:1, culture:1, beach:1, hike:1 };
SPOTS.forEach(s=>{
  if(!s.tags && s.acts) s.tags = s.acts;          // 해변·계곡은 활동이 acts에 들어있다
  if(s.level) s.lvTxt = HIKE_LEVEL[s.level] || s.level;
  /* 조사 차수마다 항목 이름이 달라서, 뜻이 같은데 화면에 안 나오던 것들을 맞춰준다 */
  if(!s.signature && s.sig)  s.signature = s.sig;      // 카페 대표메뉴
  if(!s.signature && s.menu) s.signature = s.menu;     // 맛집 대표메뉴
  if((s.cat==="cafe" || s.cat==="food") && !s.open && s.hours) s.open = s.hours;
  if(s.cat==="camp" && !s.fac && s.facility) s.fac = s.facility;
  if(!s.fee && s.price && FEE_CATS[s.cat]) s.fee = s.price;
  if(s.bug) s.bugTxt = BUG_TXT[s.bug] || null;
  /* 등산·드라이브는 예전에 코스 설명을 거리(kmTxt) 칸에 적어둔 게 많다 — 코스 칸으로 옮기고 거리는 짧게 */
  if((s.cat==="hike" || s.cat==="drive") && s.kmTxt && (s.kmTxt.indexOf("→")>=0 || s.kmTxt.length>45)){
    if(!s.course) s.course = s.kmTxt;
    s.kmTxt = s.km ? ("약 " + s.km + "km") : "";
  }
  /* 같은 뜻이 두 이름으로 들어와 같은 줄이 두 번 나오던 것 — 자세한 쪽만 남긴다 */
  const pick = (a, b)=>{           // a 를 남기고 b 를 비운다
    if(!s[a] || !s[b]) return;
    if(String(s[b]).length > String(s[a]).length) s[a] = s[b];
    s[b] = "";
  };
  pick("stop", "stopBy");          // 드라이브 정차 포인트
  pick("spend", "stay");           // 전시·구경 머무는 시간
  /* 해변에서 할 수 있는 것을 이모지 붙여 한 줄로 */
  if(s.cat === "beach" && s.acts4){
    s.acts4Txt = s.acts4.length
      ? s.acts4.map(a=>{
          const f = BEACH_ACTS.find(x=>x[0]===a);
          return (f ? f[1]+" " : "") + a;
        }).join(" · ")
      : "물에 들어가는 곳이 아니에요 — 산책·갯벌·조망 전용";
    /* 서핑·다이빙이 안 되는 곳에 서핑·다이빙 아이콘이 뜨면 헷갈린다 */
    if(s.acts4.indexOf("서핑") < 0) s.surfLv = "";
    if(s.acts4.indexOf("프리다이빙") < 0 && s.acts4.indexOf("스쿠버다이빙") < 0) s.diveInfo = "";
  }
});

/* 러닝 + 나머지를 한 배열로 (러닝은 cat이 없으니 붙여준다) */
function allSpots(){
  return RUN_SPOTS.map(s=>s.cat ? s : Object.assign({cat:"run"}, s)).concat(SPOTS);
}
function spotsOfCat(cat){ return allSpots().filter(s=>s.cat===cat); }
